}

export function jurisdictionScatter() {
  return JURISDICTION_GEO.map((j) => ({
    ...j,
    x: j.stockSharePct,
    y: j.packageSharePct,
    z: Math.max(j.packageUsdBn, 4),
  }));
}

export function sectorStackedFor(region: "eastAsia" | "northAmerica" | "europe" | "row") {
  const key =
    region === "eastAsia"
      ? "eastAsiaPct"
      : region === "northAmerica"
        ? "northAmericaPct"
        : region === "europe"
          ? "europePct"
          : "rowPct";
  return SECTOR_REGION.map((s) => ({
    sector: s.short,
    full: s.sector,
    value: s[key],
  }));
}

