"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CORRIDOR_INTENSITY,
  EU_MEMBER_SHARES,
  HEADLINE,
  JUNE_FLOW,
  METER_COMPARE,
  MONTHLY_FLOW_PATH,
  REGION_SHARES,
  SECTOR_REGION,
  SOURCE_NOTE,
  US_STATE_AWARDS,
  VINTAGE_SLOPE,
  fmtPct,
  fmtPp,
  fmtUsdBn,
  jurisdictionScatter,
  mismatchBars,
} from "@/data/fiscal-industrial-policy-geography-2026q3-data";

// viz-types: mismatch bars, region dual+pie, count??$ scatter, monthly area+line, US/EU ladders+donuts, corridor stacked, vintage slope | layout: default

type ViewId = "mismatch" | "flow" | "subnational" | "corridors";
type SubnationalLens = "us" | "eu";
type CorridorTheme = "semisPct" | "cleanPct" | "dualUsePct" | "mineralsPct";
type SlopeMetric =
  | "eastAsiaStockPct"
  | "naPackagePct"
  | "juneRowPct"
  | "usTop3StatePct";

const SKY = "#0ea5e9";
const ROSE = "#f43f5e";
const VIOLET = "#8b5cf6";
const SLATE = "#64748b";
const AMBER = "#f59e0b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function FiscalIndustrialPolicyGeography2026q3Dashboard() {
