  const sectorStack = useMemo(
    () =>
      SECTOR_REGION.map((s) => ({
        sector: s.short,
        "E. Asia": s.eastAsiaPct,
        "N. America": s.northAmericaPct,
        Europe: s.europePct,
        RoW: s.rowPct,
      })),
    [],
  );

  const slopeData = useMemo(
    () =>
      VINTAGE_SLOPE.map((v) => ({
        vintage: v.vintage.replace("Geography ", "Geo "),
        value: v[slopeMetric],
