                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="US"
                    stackId="share"
                    fill={SKY}
                    stroke={SKY}
                    fillOpacity={0.55}
                  />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="EU"
                    stackId="share"
                    fill={VIOLET}
                    stroke={VIOLET}
                    fillOpacity={0.55}
                  />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="China"
