            <>
              <ChartCard
                title="EU IPCEI / Chips Act member ladder"
                subtitle={`Tracked tip ~${fmtUsdBn(HEADLINE.euIpceiTipUsdBn, 0)} ??? ${HEADLINE.euTop3MembersLabel} ??? ${HEADLINE.euTop3MemberSharePct}%`}
              >
